/* Aurora text: FreeType + HarfBuzz + fontconfig through dlopen (aurora_text.h). */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_OUTLINE_H
#include <hb.h>
#include <hb-ft.h>
#include <fontconfig/fontconfig.h>
#include "aurora_text.h"
#include "aurora_font_data.h"   /* generated by desktop.py from fonts/Aileron-Regular.ttf: aurora_font_aileron[] */

#define SYM(name) static __typeof__(&name) p_##name
SYM(FT_Init_FreeType); SYM(FT_New_Memory_Face); SYM(FT_New_Face); SYM(FT_Set_Char_Size); SYM(FT_Select_Size); SYM(FT_Load_Glyph);
SYM(FT_Get_Char_Index); SYM(FT_Render_Glyph); SYM(FT_Outline_EmboldenXY); SYM(FT_Done_Face);
SYM(hb_ft_font_create_referenced); SYM(hb_ft_font_changed); SYM(hb_font_destroy); SYM(hb_buffer_create); SYM(hb_buffer_destroy);
SYM(hb_buffer_add_utf8); SYM(hb_buffer_guess_segment_properties); SYM(hb_shape); SYM(hb_buffer_get_glyph_infos);
SYM(hb_buffer_get_glyph_positions); SYM(hb_buffer_clear_contents);
SYM(FcInitLoadConfigAndFonts); SYM(FcPatternCreate); SYM(FcPatternDestroy); SYM(FcPatternAddString); SYM(FcPatternAddCharSet);
SYM(FcCharSetCreate); SYM(FcCharSetAddChar); SYM(FcCharSetDestroy); SYM(FcConfigSubstitute); SYM(FcDefaultSubstitute);
SYM(FcFontMatch); SYM(FcPatternGetString); SYM(FcPatternGetInteger); SYM(FcPatternGetCharSet); SYM(FcCharSetHasChar);
#undef SYM

#define FACES 24
struct face { FT_Face ft; hb_font_t* hb; char path[256]; int index; bool bitmap; int strike; int64_t size64; };
static struct face faces[FACES]; static int face_count;
static FT_Library library; static FcConfig* fc; static hb_buffer_t* shaper;
static int state;   /* 0 untried, 1 ready, -1 unavailable */
static bool fc_tried;
#define MEMO 4096       /* fallback face per codepoint (direct-mapped): face index, -1 none */
static struct { uint32_t cp; int16_t face; bool valid; } memo[MEMO];

static void* symbol(void* lib, const char* name) { return lib ? dlsym(lib, name) : NULL; }
#define LOAD(lib, name) (p_##name = (__typeof__(p_##name))symbol(lib, #name))
static bool load_libraries(void) {
    void* ft = dlopen("libfreetype.so.6", RTLD_NOW | RTLD_LOCAL);
    if (!ft || !LOAD(ft, FT_Init_FreeType) || !LOAD(ft, FT_New_Memory_Face) || !LOAD(ft, FT_New_Face) || !LOAD(ft, FT_Set_Char_Size) ||
        !LOAD(ft, FT_Select_Size) || !LOAD(ft, FT_Load_Glyph) || !LOAD(ft, FT_Get_Char_Index) || !LOAD(ft, FT_Render_Glyph) ||
        !LOAD(ft, FT_Outline_EmboldenXY) || !LOAD(ft, FT_Done_Face)) return false;
    void* hb = dlopen("libharfbuzz.so.0", RTLD_NOW | RTLD_LOCAL);
    if (!hb || !LOAD(hb, hb_ft_font_create_referenced) || !LOAD(hb, hb_ft_font_changed) || !LOAD(hb, hb_font_destroy) ||
        !LOAD(hb, hb_buffer_create) || !LOAD(hb, hb_buffer_destroy) || !LOAD(hb, hb_buffer_add_utf8) || !LOAD(hb, hb_buffer_guess_segment_properties) ||
        !LOAD(hb, hb_shape) || !LOAD(hb, hb_buffer_get_glyph_infos) || !LOAD(hb, hb_buffer_get_glyph_positions) || !LOAD(hb, hb_buffer_clear_contents))
        p_hb_shape = NULL;   /* no shaping: one glyph per character, FreeType advances */
    void* fcl = dlopen("libfontconfig.so.1", RTLD_NOW | RTLD_LOCAL);
    if (!fcl || !LOAD(fcl, FcInitLoadConfigAndFonts) || !LOAD(fcl, FcPatternCreate) || !LOAD(fcl, FcPatternDestroy) || !LOAD(fcl, FcPatternAddString) ||
        !LOAD(fcl, FcPatternAddCharSet) || !LOAD(fcl, FcCharSetCreate) || !LOAD(fcl, FcCharSetAddChar) || !LOAD(fcl, FcCharSetDestroy) ||
        !LOAD(fcl, FcConfigSubstitute) || !LOAD(fcl, FcDefaultSubstitute) || !LOAD(fcl, FcFontMatch) || !LOAD(fcl, FcPatternGetString) ||
        !LOAD(fcl, FcPatternGetInteger) || !LOAD(fcl, FcPatternGetCharSet) || !LOAD(fcl, FcCharSetHasChar))
        p_FcFontMatch = NULL;   /* no fallback fonts: characters outside Aileron are skipped */
    return true;
}
static bool add_face(FT_Face ft, const char* path, int index) {
    if (face_count == FACES) { p_FT_Done_Face(ft); return false; }
    struct face* f = &faces[face_count]; memset(f, 0, sizeof(*f)); f->ft = ft; f->index = index;
    snprintf(f->path, sizeof(f->path), "%s", path);
    f->bitmap = !(ft->face_flags & FT_FACE_FLAG_SCALABLE) && ft->num_fixed_sizes > 0;
    if (f->bitmap) {   /* colour emoji (CBDT): the largest strike, scaled down when drawn */
        int best = 0; for (int i = 1; i < ft->num_fixed_sizes; i++) if (ft->available_sizes[i].y_ppem > ft->available_sizes[best].y_ppem) best = i;
        if (p_FT_Select_Size(ft, best)) { p_FT_Done_Face(ft); return false; }
        f->strike = (int)(ft->available_sizes[best].y_ppem >> 6); if (f->strike <= 0) f->strike = 109;
    }
    if (p_hb_shape) f->hb = p_hb_ft_font_create_referenced(ft);
    face_count++; return true;
}
bool aurora_text_ready(void) {
    if (state) return state > 0;
    state = -1;
    if (getenv("AURORA_NO_FREETYPE") || !load_libraries() || p_FT_Init_FreeType(&library)) return false;
    FT_Face ui;
    if (p_FT_New_Memory_Face(library, aurora_font_aileron, (FT_Long)sizeof(aurora_font_aileron), 0, &ui) || !add_face(ui, "(Aileron)", 0)) return false;
    if (p_hb_shape && !(shaper = p_hb_buffer_create())) p_hb_shape = NULL;
    state = 1; return true;
}
bool aurora_text_needs_shaping(const char* s, int n) {
    for (int i = 0; i < n && s[i]; i++) if ((unsigned char)s[i] < 32 || (unsigned char)s[i] > 126) return true;
    return false;
}
/* ---- fallback faces ---- */
static int face_for_path(const char* path, int index) {
    for (int i = 0; i < face_count; i++) if (faces[i].index == index && !strcmp(faces[i].path, path)) return i;
    FT_Face ft; if (p_FT_New_Face(library, path, index, &ft)) return -1;
    return add_face(ft, path, index) ? face_count - 1 : -1;
}
static int fallback_lookup(uint32_t cp);
static int fallback(uint32_t cp) {
    unsigned m = (cp * 2654435761u) >> 20 & (MEMO - 1);
    if (memo[m].valid && memo[m].cp == cp) return memo[m].face;
    memo[m].valid = false;
    int found = -1;
    for (int i = 1; i < face_count && found < 0; i++) if (p_FT_Get_Char_Index(faces[i].ft, cp)) found = i;   /* an open fallback has it */
    if (found < 0) found = fallback_lookup(cp);
    memo[m].cp = cp; memo[m].face = (int16_t)found; memo[m].valid = true;
    return found;
}
static int fallback_lookup(uint32_t cp) {
    if (!p_FcFontMatch) return -1;
    if (!fc_tried) { fc_tried = true; fc = p_FcInitLoadConfigAndFonts(); }
    if (!fc) return -1;
    FcPattern* pattern = p_FcPatternCreate(); FcCharSet* set = p_FcCharSetCreate(); int found = -1;
    if (pattern && set && p_FcCharSetAddChar(set, cp) && p_FcPatternAddString(pattern, FC_FAMILY, (const FcChar8*)"sans-serif") &&
        p_FcPatternAddCharSet(pattern, FC_CHARSET, set)) {
        p_FcConfigSubstitute(fc, pattern, FcMatchPattern); p_FcDefaultSubstitute(pattern);
        FcResult result; FcPattern* match = p_FcFontMatch(fc, pattern, &result);
        FcChar8* file = NULL; int index = 0; FcCharSet* has = NULL;
        if (match && p_FcPatternGetString(match, FC_FILE, 0, &file) == FcResultMatch && file &&
            p_FcPatternGetCharSet(match, FC_CHARSET, 0, &has) == FcResultMatch && p_FcCharSetHasChar(has, cp)) {
            p_FcPatternGetInteger(match, FC_INDEX, 0, &index);
            int before = face_count; found = face_for_path((const char*)file, index);
            if (found >= before) { printf("[64] AURORA TEXT FONT %s index=%d for U+%04X\n", (const char*)file, index, (unsigned)cp); fflush(stdout); }
        }
        if (match) p_FcPatternDestroy(match);
    }
    if (set) p_FcCharSetDestroy(set);
    if (pattern) p_FcPatternDestroy(pattern);
    return found;
}
/* ---- glyph cache ---- */
struct glyph { struct glyph* next; uint16_t face; uint32_t id; int32_t size64, bold64; int16_t left, top; uint16_t w, h; bool color; uint8_t data[]; };
#define BUCKETS 2048
static struct glyph* buckets[BUCKETS]; static size_t cached_bytes;
static void cache_flush(void) {
    for (int i = 0; i < BUCKETS; i++) while (buckets[i]) { struct glyph* next = buckets[i]->next; free(buckets[i]); buckets[i] = next; }
    cached_bytes = 0;
}
static bool set_size(struct face* f, int64_t size64) {
    if (f->bitmap) return true;
    if (f->size64 == size64) return true;
    if (p_FT_Set_Char_Size(f->ft, 0, (FT_F26Dot6)size64, 72, 72)) return false;
    f->size64 = size64; if (f->hb) p_hb_ft_font_changed(f->hb);
    return true;
}
static const struct glyph* glyph(int fi, uint32_t id, int64_t size64, int bold64) {
    unsigned h = (unsigned)(fi * 7919u + id * 2654435761u + (uint32_t)size64 * 40503u + (uint32_t)bold64) % BUCKETS;
    for (struct glyph* g = buckets[h]; g; g = g->next) if (g->face == fi && g->id == id && g->size64 == size64 && g->bold64 == bold64) return g;
    struct face* f = &faces[fi];
    if (!set_size(f, size64)) return NULL;
    FT_Int32 flags = f->bitmap ? FT_LOAD_COLOR : FT_LOAD_TARGET_LIGHT | FT_LOAD_NO_BITMAP;
    if (p_FT_Load_Glyph(f->ft, id, flags)) return NULL;
    FT_GlyphSlot slot = f->ft->glyph;
    if (slot->format == FT_GLYPH_FORMAT_OUTLINE && bold64 > 0) p_FT_Outline_EmboldenXY(&slot->outline, bold64, bold64);
    if (slot->format != FT_GLYPH_FORMAT_BITMAP && p_FT_Render_Glyph(slot, FT_RENDER_MODE_NORMAL)) return NULL;
    FT_Bitmap* b = &slot->bitmap; bool color = b->pixel_mode == FT_PIXEL_MODE_BGRA;
    if (!color && b->pixel_mode != FT_PIXEL_MODE_GRAY) return NULL;
    int w = (int)b->width, hh = (int)b->rows, left = slot->bitmap_left, top = slot->bitmap_top;
    int ow = w, oh = hh;
    if (f->bitmap && f->strike > 0) {   /* scale the emoji strike to the requested size (box filter) */
        ow = (int)((int64_t)w * size64 / (f->strike * 64)); oh = (int)((int64_t)hh * size64 / (f->strike * 64));
        if (ow < 1) ow = 1; if (oh < 1) oh = 1;
        left = (int)((int64_t)left * size64 / (f->strike * 64)); top = (int)((int64_t)top * size64 / (f->strike * 64));
    }
    if (ow > 1024 || oh > 1024) return NULL;
    size_t bytes = (size_t)ow * oh * (color ? 4 : 1);
    if (cached_bytes + bytes > (16u << 20)) cache_flush();
    struct glyph* g = malloc(sizeof(*g) + bytes); if (!g) return NULL;
    *g = (struct glyph){NULL, (uint16_t)fi, id, (int32_t)size64, bold64, (int16_t)left, (int16_t)top, (uint16_t)ow, (uint16_t)oh, color};
    if (ow == w && oh == hh) {
        for (int y = 0; y < hh; y++) memcpy(g->data + (size_t)y * w * (color ? 4 : 1), b->buffer + (ptrdiff_t)y * b->pitch, (size_t)w * (color ? 4 : 1));
    } else {
        int channels = color ? 4 : 1;
        for (int y = 0; y < oh; y++) for (int x = 0; x < ow; x++) {
            int x0 = x * w / ow, x1 = (x + 1) * w / ow, y0 = y * hh / oh, y1 = (y + 1) * hh / oh;
            if (x1 <= x0) x1 = x0 + 1; if (y1 <= y0) y1 = y0 + 1;
            for (int c = 0; c < channels; c++) {
                unsigned sum = 0, n = 0;
                for (int sy = y0; sy < y1 && sy < hh; sy++) for (int sx = x0; sx < x1 && sx < w; sx++) { sum += b->buffer[(ptrdiff_t)sy * b->pitch + sx * channels + c]; n++; }
                g->data[((size_t)y * ow + x) * channels + c] = (uint8_t)(n ? sum / n : 0);
            }
        }
    }
    g->next = buckets[h]; buckets[h] = g; cached_bytes += bytes + sizeof(*g);
    return g;
}
static void blit(const struct glyph* g, int x, int y, uint32_t color, uint32_t* canvas, int cw, int ch, int stride) {
    int x0 = x + g->left, y0 = y - g->top;
    for (int row = 0; row < g->h; row++) {
        int py = y0 + row; if (py < 0 || py >= ch) continue;
        uint32_t* dst = canvas + (size_t)py * stride;
        for (int col = 0; col < g->w; col++) {
            int px = x0 + col; if (px < 0 || px >= cw) continue;
            uint32_t d = dst[px];
            if (g->color) {   /* premultiplied BGRA */
                const uint8_t* p = g->data + ((size_t)row * g->w + col) * 4; uint32_t a = p[3]; if (!a) continue;
                uint32_t r = p[2] + (((d >> 16) & 255) * (255 - a) + 127) / 255, gg = p[1] + (((d >> 8) & 255) * (255 - a) + 127) / 255, b = p[0] + ((d & 255) * (255 - a) + 127) / 255;
                dst[px] = (r > 255 ? 255 : r) << 16 | (gg > 255 ? 255 : gg) << 8 | (b > 255 ? 255 : b);
            } else {
                uint32_t a = g->data[(size_t)row * g->w + col]; if (!a) continue;
                if (a == 255) { dst[px] = color & 0xFFFFFF; continue; }
                uint32_t rb = (((color & 0xFF00FF) * a + (d & 0xFF00FF) * (255 - a)) / 255) & 0xFF00FF;
                uint32_t gg = (((color & 0x00FF00) * a + (d & 0x00FF00) * (255 - a)) / 255) & 0x00FF00;
                dst[px] = rb | gg;
            }
        }
    }
}
/* ---- runs ---- */
static uint32_t decode(const char* s, int n, int* at) {   /* UTF-8; invalid bytes come back as U+FFFD */
    const unsigned char* u = (const unsigned char*)s; int i = *at; uint32_t c = u[i];
    int extra = c < 0x80 ? 0 : (c & 0xE0) == 0xC0 ? 1 : (c & 0xF0) == 0xE0 ? 2 : (c & 0xF8) == 0xF0 ? 3 : -1;
    if (extra < 0 || (extra && i + extra >= n)) { *at = i + 1; return extra ? 0xFFFD : c; }
    uint32_t v = extra ? c & (0x3F >> extra) : c;
    for (int k = 1; k <= extra; k++) { if ((u[i + k] & 0xC0) != 0x80) { *at = i + 1; return 0xFFFD; } v = v << 6 | (u[i + k] & 0x3F); }
    *at = i + 1 + extra;
    if ((extra == 1 && v < 0x80) || (extra == 2 && v < 0x800) || (extra == 3 && (v < 0x10000 || v > 0x10FFFF)) || (v >= 0xD800 && v < 0xE000)) return 0xFFFD;
    return v;
}
static int64_t draw_run(int fi, const char* s, int n, int64_t size64, int bold64, int64_t pen, int baseline, uint32_t color, uint32_t* canvas, int cw, int ch, int stride) {
    struct face* f = &faces[fi];
    int64_t scale_num = f->bitmap ? size64 : 1, scale_den = f->bitmap ? (int64_t)f->strike * 64 : 1;
    if (!set_size(f, size64)) return pen;
    int64_t extra = bold64 * 3 / 4;   /* emboldening widens the pen like the built-in semibold */
    if (f->hb && p_hb_shape) {
        p_hb_buffer_clear_contents(shaper); p_hb_buffer_add_utf8(shaper, s, n, 0, n); p_hb_buffer_guess_segment_properties(shaper);
        p_hb_shape(f->hb, shaper, NULL, 0);
        unsigned count = 0; hb_glyph_info_t* info = p_hb_buffer_get_glyph_infos(shaper, &count); hb_glyph_position_t* pos = p_hb_buffer_get_glyph_positions(shaper, &count);
        for (unsigned i = 0; i < count; i++) {
            int64_t dx = (int64_t)pos[i].x_offset * scale_num / scale_den, dy = (int64_t)pos[i].y_offset * scale_num / scale_den;
            if (canvas) { const struct glyph* g = glyph(fi, info[i].codepoint, size64, bold64); if (g) blit(g, (int)((pen + dx + 32) >> 6), baseline - (int)((dy + 32) >> 6), color, canvas, cw, ch, stride); }
            pen += (int64_t)pos[i].x_advance * scale_num / scale_den + extra;
        }
        return pen;
    }
    for (int at = 0; at < n;) {
        uint32_t cp = decode(s, n, &at); FT_UInt id = p_FT_Get_Char_Index(f->ft, cp); if (!id) continue;
        if (p_FT_Load_Glyph(f->ft, id, f->bitmap ? FT_LOAD_COLOR : FT_LOAD_TARGET_LIGHT | FT_LOAD_NO_BITMAP)) continue;
        int64_t advance = (int64_t)f->ft->glyph->advance.x * scale_num / scale_den;
        if (canvas) { const struct glyph* g = glyph(fi, id, size64, bold64); if (g) blit(g, (int)((pen + 32) >> 6), baseline, color, canvas, cw, ch, stride); }
        pen += advance + extra;
    }
    return pen;
}
int64_t aurora_text_run(const char* s, int n, int size64, int bold64, int x, int baseline, uint32_t color, uint32_t* canvas, int cw, int ch, int stride) {
    if (!aurora_text_ready() || n <= 0 || size64 <= 0) return 0;
    if (size64 > 512 * 64) size64 = 512 * 64;
    int64_t pen = (int64_t)x * 64, start = pen;
    int at = 0, run_start = 0, run_face = -2, missing = 0;
    while (at < n && s[at]) {   /* runs of characters one face shows; a character no face has leaves a gap */
        int here = at; uint32_t cp = decode(s, n, &at), fi;
        if (cp < 32 || cp == 0x7F) fi = (uint32_t)-1;
        else if (p_FT_Get_Char_Index(faces[0].ft, cp)) fi = 0;
        else if (run_face >= 0 && (cp == 0x200D || cp == 0xFE0F || (cp >= 0x300 && cp < 0x370) || p_FT_Get_Char_Index(faces[run_face].ft, cp))) fi = (uint32_t)run_face;
        else fi = (uint32_t)fallback(cp);
        if ((int)fi != run_face) {
            if (run_face >= 0) pen = draw_run(run_face, s + run_start, here - run_start, size64, bold64, pen, baseline, color, canvas, cw, ch, stride);
            run_start = here; run_face = (int)fi;
        }
        if ((int)fi < 0) { missing++; pen += size64 / 2; }
    }
    if (run_face >= 0) pen = draw_run(run_face, s + run_start, at - run_start, size64, bold64, pen, baseline, color, canvas, cw, ch, stride);
    (void)missing;
    return pen - start;
}
